"""Normalize release records at the input boundary."""


class JournalError(ValueError):
    pass


def _id_list(value):
    """Validate an array of nonempty change IDs, deduplicated in first-seen order."""
    if not isinstance(value, list):
        raise JournalError("invalid-change")
    seen = set()
    ids = []
    for item in value:
        if not isinstance(item, str) or not item:
            raise JournalError("invalid-change")
        if item not in seen:
            seen.add(item)
            ids.append(item)
    return ids


def read_changes(records):
    """Validate change records; identical duplicates collapse to one.

    A malformed record fails outright. An otherwise valid record also fails
    with conflicting-change when its ID repeats with a different component,
    unit count or set of dependencies.
    """
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    accepted = []
    first = {}
    for row in records:
        if not isinstance(row, dict):
            raise JournalError("invalid-change")
        change_id = row.get("id")
        component = row.get("component")
        units = row.get("units")
        if (not isinstance(change_id, str) or not change_id
                or not isinstance(component, str) or not component
                or type(units) is not int or units < 1):
            raise JournalError("invalid-change")
        depends_on = _id_list(row.get("depends_on", []))
        change = {
            "id": change_id,
            "component": component,
            "units": units,
            "depends_on": depends_on,
        }
        known = first.get(change_id)
        if known is None:
            first[change_id] = change
            accepted.append(change)
        elif (known["component"], known["units"], set(known["depends_on"])) != (
                component, units, set(depends_on)):
            raise JournalError("conflicting-change")
    return accepted


def read_journal(applied):
    """Validate the persisted applied journal supplied by the caller."""
    return _id_list(applied)

