"""Compose policy and journal data into a plan."""
import heapq

from journal import JournalError, read_changes, read_journal
from policy import PolicyError, effective_limit, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def order_graph(changes, applied):
    """Return the full deterministic topological order of all changes.

    Missing dependency targets or journal IDs outside the graph fail with
    unknown-dependency; a cycle anywhere fails with dependency-cycle.
    """
    by_id = {row["id"]: row for row in changes}
    for row in changes:
        for dep in row["depends_on"]:
            if dep not in by_id:
                raise JournalError("unknown-dependency")
    for change_id in applied:
        if change_id not in by_id:
            raise JournalError("unknown-dependency")

    blockers = {row["id"]: set(row["depends_on"]) for row in changes}
    dependents = {change_id: set() for change_id in by_id}
    for row in changes:
        for dep in row["depends_on"]:
            dependents[dep].add(row["id"])

    ready = [change_id for change_id, deps in blockers.items() if not deps]
    heapq.heapify(ready)
    order = []
    while ready:
        change_id = heapq.heappop(ready)
        order.append(change_id)
        for dependent in dependents[change_id]:
            remaining = blockers[dependent]
            remaining.discard(change_id)
            if not remaining:
                heapq.heappush(ready, dependent)
    if len(order) != len(by_id):
        raise JournalError("dependency-cycle")
    return order, by_id


def retained_set(by_id, applied, retain):
    """Expand the caller's retain list to the IDs that cannot be rolled back.

    Each retained change must already be applied. The retained closure also
    holds every applied transitive dependency those retained changes require.
    """
    if not isinstance(retain, list):
        raise JournalError("invalid-retain")
    kept = set()
    pending = []
    for item in retain:
        if not isinstance(item, str) or not item:
            raise JournalError("invalid-retain")
        if item not in applied:
            raise JournalError("invalid-retain")
        if item not in kept:
            kept.add(item)
            pending.append(item)
    while pending:
        for dep in by_id[pending.pop()]["depends_on"]:
            if dep in applied and dep not in kept:
                kept.add(dep)
                pending.append(dep)
    return kept


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget = limit_for(request)
        action = request.get("action")
        environment = request.get("environment")
        changes = read_changes(request.get("changes"))
        applied = set(read_journal(request.get("applied", [])))
        order, by_id = order_graph(changes, applied)
        if action == "rollback":
            kept = retained_set(by_id, applied, request.get("retain", []))
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    if action == "rollback":
        actions = [change_id for change_id in reversed(order)
                   if change_id in applied and change_id not in kept]
    else:
        actions = [change_id for change_id in order if change_id not in applied]

    units = sum(by_id[change_id]["units"] for change_id in actions)
    limit = effective_limit(environment, action, budget)
    if limit is not None and units > limit:
        return failure("budget-exceeded")
    return {"status": "ok", "actions": actions, "units": units}

