"""Validate release policy before computing actions."""

ENVIRONMENTS = {"staging", "production"}
ACTIONS = {"plan", "rollback"}

# G2: this release is staging-only; production plan and rollback are frozen.
FROZEN_ENVIRONMENTS = {"production"}
# G2: the largest request budget a staging plan may actually use.
STAGING_PLAN_LIMIT = 3


class PolicyError(ValueError):
    pass


def limit_for(request):
    """Validate environment, action and budget, returning the budget value.

    Both supported actions require a nonnegative integer budget; rollback
    validates it without using it as a cap. A frozen environment fails with
    production-frozen before the budget or any other request field is read.
    """
    environment = request.get("environment")
    if environment in FROZEN_ENVIRONMENTS:
        raise PolicyError("production-frozen")
    if environment not in ENVIRONMENTS:
        raise PolicyError("invalid-environment")
    if request.get("action") not in ACTIONS:
        raise PolicyError("unsupported-action")
    budget = request.get("budget")
    if type(budget) is not int or budget < 0:
        raise PolicyError("invalid-budget")
    return budget


def effective_limit(environment, action, budget):
    """Return the budget an action may consume, or None when uncapped.

    Rollback is never capped. A staging plan may use at most the smaller of
    the request budget and the staging plan limit.
    """
    if action == "rollback":
        return None
    if environment == "staging":
        return min(budget, STAGING_PLAN_LIMIT)
    return budget

