    """Return the full deterministic topological order of change IDs.

    Ties among currently eligible changes resolve lexicographically by ID.
    Applied journal entries satisfy dependencies; missing targets, unknown
    applied IDs and cycles are rejected here.
    """
    known = {row["id"] for row in changes}
    for entry in applied:
        if entry not in known:
            raise PlanError("unknown-dependency")
    pending = {}
    dependents = {key: [] for key in known}
    for row in changes:
        remaining = set()
        for dependency in row["depends_on"]:
            if dependency not in known:
                raise PlanError("unknown-dependency")
            if dependency not in applied:
                remaining.add(dependency)
        pending[row["id"]] = remaining
        for dependency in remaining:
            dependents[dependency].append(row["id"])

    ready = [key for key, remaining in pending.items() if not remaining]
    heapq.heapify(ready)
    order = []
    while ready:
        current = heapq.heappop(ready)
        order.append(current)
        for follower in dependents[current]:
            pending[follower].discard(current)
            if not pending[follower]:
                heapq.heappush(ready, follower)
    if len(order) != len(changes):
        raise PlanError("dependency-cycle")
    return order


