"""Compose policy and journal data into a plan."""
import heapq

from journal import JournalError, read_applied, read_changes, read_retain
from policy import PolicyError, effective_budget, limit_for


class PlanError(ValueError):
    pass


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def topological_order(changes, applied):
    """Return the full deterministic topological order of change IDs.

    Ties among currently eligible changes resolve lexicographically by ID.
    Applied journal entries satisfy dependencies; missing targets, unknown
    applied IDs and cycles are rejected here.
    """
    known = {row["id"] for row in changes}
    for entry in applied:
        if entry not in known:
            raise PlanError("unknown-dependency")
    pending = {}
    dependents = {key: [] for key in known}
    for row in changes:
        remaining = set()
        for dependency in row["depends_on"]:
            if dependency not in known:
                raise PlanError("unknown-dependency")
            if dependency not in applied:
                remaining.add(dependency)
        pending[row["id"]] = remaining
        for dependency in remaining:
            dependents[dependency].append(row["id"])

    ready = [key for key, remaining in pending.items() if not remaining]
    heapq.heapify(ready)
    order = []
    while ready:
        current = heapq.heappop(ready)
        order.append(current)
        for follower in dependents[current]:
            pending[follower].discard(current)
            if not pending[follower]:
                heapq.heappush(ready, follower)
    if len(order) != len(changes):
        raise PlanError("dependency-cycle")
    return order


def retained_ids(changes, retain):
    """G2: the retained set plus its transitive applied dependencies."""
    depends_by_id = {row["id"]: row["depends_on"] for row in changes}
    retained = set()
    stack = sorted(retain, reverse=True)
    while stack:
        current = stack.pop()
        if current in retained:
            continue
        retained.add(current)
        stack.extend(sorted(depends_by_id[current], reverse=True))
    return retained


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        # Policy first: a production freeze wins over any graph or budget fault.
        _, action, budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied"))
        retain = read_retain(request.get("retain"), applied) if action == "rollback" else []
        order = topological_order(changes, set(applied))
    except (PolicyError, JournalError, PlanError) as exc:
        return failure(str(exc))

    units_by_id = {row["id"]: row["units"] for row in changes}
    if action == "rollback":
        # Budget is validated but never caps a rollback in any environment.
        keep = retained_ids(changes, retain)
        actions = [key for key in reversed(order) if key in applied and key not in keep]
    else:
        actions = [key for key in order if key not in applied]
        if sum(units_by_id[key] for key in actions) > effective_budget(budget):
            return failure("budget-exceeded")
    units = sum(units_by_id[key] for key in actions)
    return {"status": "ok", "actions": actions, "units": units}

