"""Normalize release records and replay state at the input boundary.

Call direction: planner.py imports this module; journal.py imports nothing local, so it
stays at the bottom of the import chain (policy.py likewise). Membership in the request
body, which records survive replay, and whether edges/journal entries name a known change
are decided here; ordering and budget arithmetic stay in planner.py. Every domain failure
is raised as JournalError whose message is the wire error code, so planner.py can assemble
the single error shape without re-mapping codes.
"""


class JournalError(ValueError):
    """Domain failure carrying the SPEC error code as its message."""


def _id_list(value):
    # SPEC: `depends_on`/`applied` default to empty arrays, and any non-array or malformed
    # element is `invalid-change`. A bare string is iterable but is not an array, so it is
    # rejected here instead of being silently exploded into per-character IDs.
    if not isinstance(value, list):
        raise JournalError("invalid-change")
    for item in value:
        if not isinstance(item, str) or not item:
            raise JournalError("invalid-change")
    return value


def _dependency_set(value):
    # Replay equality is defined over the *set* of dependencies (SPEC line 11), so ordering
    # and repeated edges must not make two otherwise identical records look different.
    return frozenset(_id_list(value))


def _read_record(row):
    if (not isinstance(row, dict) or not isinstance(row.get("id"), str) or not row["id"]
            or not isinstance(row.get("component"), str) or not row["component"]
            # `type(...) is not int` rather than isinstance: SPEC excludes booleans, which
            # are int subclasses. `units` must be a positive integer.
            or type(row.get("units")) is not int or row["units"] < 1):
        raise JournalError("invalid-change")
    return {
        "id": row["id"],
        "component": row["component"],
        "units": row["units"],
        "depends_on": _dependency_set(row.get("depends_on", [])),
    }


def read_changes(records):
    """Validate `changes`, collapse identical replays, and return unique records by ID."""
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    unique = {}
    for row in records:
        record = _read_record(row)
        known = unique.get(record["id"])
        if known is None:
            unique[record["id"]] = record
        elif known != record:
            # Same ID but different component/units/dependency set: the caller is replaying
            # an edited record, so neither copy can be trusted as the journal truth.
            raise JournalError("conflicting-change")
        # Identical replays fall through and collapse to the first copy, so units are
        # accounted once; planner sums this mapping, never the raw array.
    return unique


def read_applied(request, unique):
    """Validate the caller-supplied persisted journal and check it names known changes."""
    applied = _id_list(request.get("applied", []))
    for change_id in applied:
        if change_id not in unique:
            # An applied entry with no matching change cannot be ordered against the graph,
            # so it is a broken journal reference rather than an ignorable extra.
            raise JournalError("unknown-dependency")
    return frozenset(applied)


def check_targets(unique):
    """Reject dependency edges whose target change is absent from the replayed records."""
    for record in unique.values():
        for target in record["depends_on"]:
            if target not in unique:
                raise JournalError("unknown-dependency")

planner.py.text:
"""Compose policy and journal data into a plan.

Import direction is planner -> {journal, policy} and must stay that way: journal and policy
never import planner, so they cannot assemble a result or reach back into ordering. This
module alone owns graph order, budget arithmetic and the single ok/error result shape.

Failure discipline: every domain problem is raised by a callee and converted here into
the exact error shape with empty `actions` and `units` 0, so a rejected request can never
leak a partial action list (SPEC line 7).
"""
import heapq

from journal import JournalError, check_targets, read_applied, read_changes
from policy import PolicyError, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def success(ids, units):
    return {"status": "ok", "actions": ids, "units": units}


def topological_order(unique):
    """Return change IDs in deterministic dependency order.

    The eligible set is kept in a heap so the smallest ID is always taken first; this is
    what makes replay deterministic across runs and across Python builds (a plain set
    iteration would vary). Callers must have run `check_targets` first, so every edge here
    points at a known ID.
    """
    pending = {change_id: set(record["depends_on"]) for change_id, record in unique.items()}
    dependents = {change_id: [] for change_id in unique}
    for change_id, deps in pending.items():
        for target in deps:
            dependents[target].append(change_id)
    ready = [change_id for change_id, deps in pending.items() if not deps]
    heapq.heapify(ready)
    order = []
    while ready:
        change_id = heapq.heappop(ready)
        order.append(change_id)
        for dependent in dependents[change_id]:
            pending[dependent].discard(change_id)
            if not pending[dependent]:
                heapq.heappush(ready, dependent)
    if len(order) != len(unique):
        # Some node never became ready, which for a finite digraph means a cycle. It is
        # checked after the full sweep so a cycle anywhere fails the request even when a
        # cycle-free prefix could already have been ordered.
        raise JournalError("dependency-cycle")
    return order


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget = limit_for(request)
        unique = read_changes(request.get("changes"))
        applied = read_applied(request, unique)
        check_targets(unique)
        order = topological_order(unique)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    if request["action"] == "rollback":
        # Only applied changes roll back, and the full order is reversed *before* filtering
        # so dependents are undone before the things they depend on. Budget is not a cap
        # here (SPEC line 14): capping would silently truncate a release history.
        ids = [change_id for change_id in reversed(order) if change_id in applied]
        return success(ids, sum(unique[change_id]["units"] for change_id in ids))
    # plan: applied entries satisfy dependencies but ship already, so they consume no new
    # budget; the cap is applied to the emitted set only, after replay/dedup.
    ids = [change_id for change_id in order if change_id not in applied]
    units = sum(unique[change_id]["units"] for change_id in ids)
    if units > budget:
        # Checked after the emitted set is known, so budget comparisons use post-replay units.
        return failure("budget-exceeded")
    return success(ids, units)

