        raise JournalError("invalid-change")
    for item in value:
        if not isinstance(item, str) or not item:
            raise JournalError("invalid-change")
    return value


def _dependency_set(value):
    # Replay equality is defined over the *set* of dependencies (SPEC line 11), so ordering
    # and repeated edges must not make two otherwise identical records look different.
    return frozenset(_id_list(value))


def _read_record(row):
    if (not isinstance(row, dict) or not isinstance(row.get("id"), str) or not row["id"]
            or not isinstance(row.get("component"), str) or not row["component"]
            # `type(...) is not int` rather than isinstance: SPEC excludes booleans, which
            # are int subclasses. `units` must be a positive integer.
            or type(row.get("units")) is not int or row["units"] < 1):
        raise JournalError("invalid-change")
